var a=63;var t=[{id:`cooking-063-01`,theoryId:63,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which spice is most associated with warm cinnamon-like aroma?`,ua:`Яка спеція має характерний теплий аромат кориці?`},explanation:{en:`Cinnamon contains aromatic compounds such as cinnamaldehyde.`,ua:`Характерний аромат кориці пов’язаний, зокрема, з коричним альдегідом.`},options:[{id:`a`,text:{en:`Cinnamon bark`,ua:`Кориця`}},{id:`b`,text:{en:`Dried dill`,ua:`Сушений кріп`}},{id:`c`,text:{en:`Bay leaf`,ua:`Лавровий лист`}}],answer:{optionIds:[`a`]}},{id:`cooking-063-02`,theoryId:63,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`All ground spices remain equally aromatic for an unlimited time.`,ua:`Усі мелені спеції зберігають однаково сильний аромат без обмежень у часі.`},explanation:{en:`Aromatic compounds gradually dissipate and oxidize, especially after grinding.`,ua:`Після помелу ароматичні речовини поступово вивітрюються та окиснюються.`},answer:{value:!1}},{id:`cooking-063-03`,theoryId:63,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match the spice to its typical flavor profile.`,ua:`Поєднайте спецію з типовим ароматичним профілем.`},explanation:{en:`Different volatile compounds create recognizable spice notes.`,ua:`Різні леткі сполуки формують впізнавані аромати спецій.`},leftItems:[{id:`l1`,text:{en:`Cumin`,ua:`Кумин (зіра)`}},{id:`l2`,text:{en:`Cardamom`,ua:`Кардамон`}},{id:`l3`,text:{en:`Black pepper`,ua:`Чорний перець`}}],rightItems:[{id:`r3`,text:{en:`Pungent and woody`,ua:`Пекучий та деревний`}},{id:`r2`,text:{en:`Floral and citrus-like`,ua:`Квітковий і цитрусовий`}},{id:`r1`,text:{en:`Earthy and warm`,ua:`Землистий і теплий`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-063-04`,theoryId:63,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A curry tastes harsh from too much clove. What is a realistic correction?`,ua:`У карі надто різкий смак гвоздики. Яке виправлення реалістичне?`},explanation:{en:`Dilution reduces relative concentration; strong spices cannot be reliably erased.`,ua:`Розбавлення зменшує відносну концентрацію; сильні спеції не можна гарантовано «стерти».`},options:[{id:`a`,text:{en:`Dilute with more unsalted base ingredients and rebalance`,ua:`Розбавити додатковими несолоними базовими інгредієнтами та збалансувати`}},{id:`b`,text:{en:`Add more cloves`,ua:`Додати ще гвоздики`}},{id:`c`,text:{en:`Assume further boiling deletes every clove aroma`,ua:`Вважати, що подальше кипіння повністю усуне аромат гвоздики`}}],answer:{optionIds:[`a`]}},{id:`cooking-063-05`,theoryId:63,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which storage practice harms spice quality?`,ua:`Який спосіб зберігання погіршує якість спецій?`},explanation:{en:`Heat, moisture and oxygen accelerate quality loss.`,ua:`Тепло, волога та кисень прискорюють втрату якості.`},options:[{id:`a`,text:{en:`Keeping spices sealed away from sunlight`,ua:`Тримати спеції щільно закритими подалі від сонця`}},{id:`b`,text:{en:`Using small quantities`,ua:`Використовувати невеликі запаси`}},{id:`c`,text:{en:`Storing open ground spices above a steaming hob`,ua:`Зберігати відкриті мелені спеції над паруючою плитою`}}],answer:{optionIds:[`c`]}}];var n={theoryId:63,exercises:t};export{n as default,t as exercises,a as theoryId};